pub fn lis(xs: List[Int]) -> List[Int] {
  let n = xs.len()
  var lens: List[Int] = range(0, n).map(fn(_k) => 0)
  var i = n - 1
  while i >= 0 {
    var best = 1
    for j in range(i + 1, n) {
      if xs.get_or(j, 0) > xs.get_or(i, 0) and lens.get_or(j, 0) + 1 > best {
        best = lens.get_or(j, 0) + 1
      }
    }
    lens = lens.set(i, best)
    i = i - 1
  }
  let max_len = lens.max().unwrap_or(0)
  var out: List[Int] = []
  var prev = -1
  var need = max_len
  while need > 0 {
    var pick = -1
    for j in range(prev + 1, n) {
      if lens.get_or(j, 0) == need and (prev == -1 or xs.get_or(j, 0) > xs.get_or(prev, 0)) {
        if pick == -1 or xs.get_or(j, 0) < xs.get_or(pick, 0) {
          pick = j
        }
      }
    }
    out = out.push(xs.get_or(pick, 0))
    prev = pick
    need = need - 1
  }
  return out
}
